const LANG_LIST = [["en", "English", "영어"], ["vi", "Tiếng Việt", "베트남어"], ["ne", "नेपाली", "네팔어"], ["my", "Myanmar", "미얀마어"], ["lo", "ພາສາລາວ", "라오스어"]];
